import { button, coins, esc, header } from './views.js';
import { icon } from './icons.js';
import { GOLF_COURSES, golfPar, golfHoleCount, courseRecordKey } from './golf-courses.js';
import { COURSES, getHole, relative } from './courses.js';
import { featuredCourses } from './rotating-courses.js';
export function courseMenu(ui) {
  const golf=ui.mode==='golf',courses=golf?GOLF_COURSES:COURSES;
  const card=(i,feature)=>{
    const c=courses[i],count=golf?golfHoleCount(i):9,unlocked=ui.localPreview||ui.progress.level.level>=c.level;
    const best=ui.progress.data.bests[courseRecordKey(ui.mode,i)],par=Array.from({length:count},(_,j)=>golf?golfPar(i,j):getHole(i,j).par).reduce((a,b)=>a+b,0);
    const reset=feature?.ends?new Date(feature.ends).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'';
    return `<article class="arcade-course ${feature?.index===17?'monthly-course':''} ${feature?'featured-course':''}" data-card><img data-course-preview="${ui.mode}:${i}" src="${ui.world.thumbnail(i,ui.mode)}" alt="${esc(c.name)}" loading="lazy" decoding="async"><div class="arcade-course-copy"><div class="course-card-meta">${feature?`<span class="course-slot" title="${!feature.ends?'Always available':feature.label==='Seasonal course'?'Ends':'Changes'} ${esc(reset)}">${esc(feature.label)}</span>`:''}<span>${count} ${count===1?'hole':'holes'} · Par ${par}</span></div><${golf?'h3':'h2'}>${esc(c.name)}</${golf?'h3':'h2'}><p>${esc(c.subtitle)}</p><div class="arcade-course-record"><span>${unlocked?esc(c.difficulty):'Level '+c.level+' · Practice available'}</span><span>Best ${best?relative(best.score):'-'}</span></div>${button(icon('play')+(unlocked?'Play':'Practice'),unlocked?'start':'practice',`data-course="${i}" data-card-primary aria-label="${unlocked?'Play':'Practice'} ${esc(c.name)}"`,'arcade-button arcade-primary')}</div></article>`;
  };
  const features=featuredCourses(),allFeatures=features;
  const section=(id,title,note,cards)=>`<section class="course-section course-section-${id}" aria-labelledby="${id}-courses-heading"><div class="course-section-heading"><h2 id="${id}-courses-heading">${title}</h2><span>${note}</span></div><div class="arcade-courses" style="--course-count:${cards.length}">${cards.join('')}</div></section>`;
  const content=golf?`<div class="course-sections">${section('classic','Classic courses','The original three-hole rounds',[0,1,2].map(i=>card(i)))}${section('featured','More to play','Monthly · Seasonal · Weekly · Daily · Nine holes',features.map(f=>card(f.index,f)))}</div>`:`<div class="arcade-courses">${courses.map((_,i)=>card(i)).join('')}</div>`;
  return `${header(ui)}<main class="arcade-page course-menu ${golf?'full-golf-menu':''}"><header class="arcade-page-header">${button('← Back','home','','arcade-button')}<div class="course-page-title"><span class="eyebrow">FIND YOUR FAIRWAY</span><h1>Pick your next round.</h1><p>Classic courses, rotating adventures, and a change of pace.</p></div><span>${coins(ui.progress.data.coins)}</span></header><section class="arcade-page-content"><nav class="arcade-switch" aria-label="Golf mode">${[['golf','Full golf'],['mini','Mini-golf']].map(([id,label])=>button(label,'mode',`data-id="${id}" aria-pressed="${ui.mode===id}"`,'arcade-button')).join('')}${golf?`<span class="course-menu-note">${allFeatures.length+3} courses · One clubhouse</span>`:''}</nav>${content}<footer class="arcade-course-footer"><div>${button('Community maps','community','','arcade-button')}${button('Map editor · Level 10','editor','','arcade-button')}</div><small>Daily: midnight UTC · Weekly: Monday midnight UTC. Practice and custom maps do not award coins or leaderboard results.</small></footer></section></main>`;
}
